@List.modify_nil : ∀ {α : Type u_1} (f : α → α) (i : Nat), [].modify i f = []
@List.modify_zero_cons : ∀ {α : Type u_1} (f : α → α) (a : α) (l : List α), (a :: l).modify 0 f = f a :: l
@List.modify_succ_cons : ∀ {α : Type u_1} (f : α → α) (a : α) (l : List α) (i : Nat),
  (a :: l).modify (i + 1) f = a :: l.modify i f
